(()=>{'use strict';
const games=[["count-bus-stops","バスていを かぞえよう","数","🚌","バスが とまった かずを かぞえる"],["shape-tunnel-arch","トンネルの いりぐち","形","🚇","トンネルの かたちを あわせる"],["color-ferry-flags","フェリーの はた","色","⛴️","ふねの はたを いろで えらぶ"],["memory-heli-landing","ヘリの ちゃくりくば","記憶","🚁","ヘリが おりた ばしょを おぼえる"],["sound-ambulance-siren","きゅうきゅうの サイレン","音","🚑","サイレンの おとの かずを きく"],["direction-tractor-field","トラクターの はたけ","方向","🚜","やじるしで はたけを すすむ"],["order-airport-boarding","ひこうきに のろう","順序","✈️","きっぷ・ゲート・ひこうきの じゅん"],["observation-harbor-boats","みなとの ふねさがし","観察","🚢","おなじ ふねを さがす"],["cause-traffic-gate","ふみきりを あけよう","因果関係","🚦","でんしゃが すぎたら ゲートを あける"],["operation-forklift","フォークリフトで はこぼう","乗り物操作","🚛","もちあげて はこんで おろす"]],id=new URLSearchParams(location.search).get('id'),mode=Math.max(0,games.findIndex(x=>x[0]===id)),g=games[mode],$=id=>document.getElementById(id);let round=0,step=0,q,locked=true,rev=0,ctx,last='',soundBusy=false;
const shuffle=a=>a.slice().sort(()=>Math.random()-.5),wait=t=>new Promise(r=>setTimeout(r,t));
function say(t){last=t;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ja-JP';u.rate=.82;speechSynthesis.speak(u)}catch{}}
function tone(f=550){try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();const o=ctx.createOscillator(),v=ctx.createGain(),t=ctx.currentTime;o.type='triangle';o.frequency.value=f;v.gain.setValueAtTime(.001,t);v.gain.exponentialRampToValueAtTime(.045,t+.035);v.gain.exponentialRampToValueAtTime(.001,t+.27);o.connect(v).connect(ctx.destination);o.start(t);o.stop(t+.28)}catch{}}
async function siren(n,r){if(soundBusy)return;soundBusy=true;for(let i=0;i<n;i++){if(r!==rev)break;tone(i%2?620:760);await wait(460)}soundBusy=false}
function paint(scene,prompt,options){$('visual').textContent=scene;$('instruction').textContent=prompt;$('feedback').textContent='';$('progress').textContent=(round+1)+' / 3';$('choices').replaceChildren();options.forEach(x=>{const b=document.createElement('button');b.className='choice';b.textContent=x;b.onclick=()=>choose(x);$('choices').append(b)});say(prompt);locked=false}
function startRound(){locked=true;step=0;const n=round+1;switch(mode){
case 0:{q={answer:'🚌 とまる',remaining:n+1,total:n+1};paint('🚌  🛑'.repeat(n+1)+'\n0 / '+(n+1),'バスていで '+(n+1)+'かい とまろう',['🚌 とまる','🔁 やりなおす']);break}
case 1:{const a=['◯','△','□'],target=a[round];q={answer:target};paint('🚇  '+target+'  🚇','トンネルの いりぐちと おなじ かたちを おしてね',shuffle(a));break}
case 2:{const a=['🔴','🔵','🟡'],target=a[round];q={answer:target};paint('⛴️  🏳️  '+target,'フェリーの はたを おなじ いろに しよう',shuffle(a));break}
case 3:{const target=1+Math.floor(Math.random()*4);q={answer:String(target),hidden:false};paint('🚁  '+[1,2,3,4].map(i=>i===target?'🚁':'🟩').join('  '),'ヘリが おりた ばしょを おぼえてね',['👀 おぼえた']);break}
case 4:{q={answer:String(n+1),count:n+1};paint('🚑  🔊','サイレンが なんかい なるか きこう',['1','2','3','4','🔊 もういちど']);siren(q.count,rev);break}
case 5:{q={path:[['➡️','⬆️'],['⬆️','➡️','⬇️'],['➡️','⬆️','➡️','⬇️']][round],position:0};q.answer=q.path[0];paint('🚜  🌾  '+'▫️'.repeat(q.path.length)+'  🏁','やじるしで トラクターを すすめよう',shuffle(['⬅️','➡️','⬆️','⬇️']));break}
case 6:{q={path:['🎫 きっぷ','🚪 ゲート','✈️ のる'],position:0};q.answer=q.path[0];paint('🎫  🚪  ✈️','ひこうきに のる じゅんばんを えらぼう',shuffle(q.path));break}
case 7:{const boats=['⛵','🚢','🛶'],target=boats[round];q={answer:target};paint('🌊  '+shuffle([...boats,'🚤','⛴️']).join('  '),'みなとで '+(target==='⛵'?'ヨット':target==='🚢'?'おおきな ふね':'カヌー')+'を さがそう',shuffle(boats));break}
case 8:{q={path:['🚆 でんしゃが とおる','🚦 あかで まつ','⬆️ ゲートを あける'],position:0};q.answer=q.path[0];paint('🚦  🚆  🚧','でんしゃが すぎてから ゲートを あけよう',shuffle(q.path));break}
case 9:{q={path:['⬆️ あげる','➡️ はこぶ','⬇️ おろす'],position:0,boxes:n};q.answer=q.path[0];paint('🚛  📦'.repeat(n),'フォークリフトで にもつを あげて はこぼう',shuffle(q.path));break}
}}
function wrong(){locked=false;$('feedback').textContent='おしいね。 もういちど 👆';say('おしいね。 もういちど おしてね')}
async function success(r){tone(830);$('feedback').textContent='できたね！ ⭐';say('せいかい！ できたね');await wait(650);if(r!==rev)return;round++;round<3?startRound():finish()}
async function choose(x){if(locked)return;locked=true;const r=rev;
if(mode===3&&!q.hidden){q.hidden=true;$('visual').textContent='🚁  ❔ ❔ ❔ ❔';$('instruction').textContent='ヘリは なんばんに おりたかな？';$('choices').replaceChildren();['1','2','3','4'].forEach(y=>{const b=document.createElement('button');b.className='choice';b.textContent=y;b.onclick=()=>choose(y);$('choices').append(b)});say($('instruction').textContent);locked=false;return}
if(mode===4&&x==='🔊 もういちど'){siren(q.count,r);locked=false;return}
if(mode===0){if(x==='🔁 やりなおす'){q.remaining=q.total;$('visual').textContent='🚌  🛑'.repeat(q.total)+'\n0 / '+q.total;locked=false;return}q.remaining--;tone(480);$('visual').textContent='🚌  🛑'.repeat(q.total)+'\n'+(q.total-q.remaining)+' / '+q.total;if(q.remaining>0){locked=false;return}return success(r)}
if(mode===5||mode===6||mode===8||mode===9){if(x!==q.answer)return wrong();q.position++;tone(520);$('visual').textContent=g[3]+'  '+'⭐'.repeat(q.position)+'  🏁';if(q.position<q.path.length){q.answer=q.path[q.position];$('instruction').textContent='つぎは '+q.answer;say($('instruction').textContent);locked=false;return}return success(r)}
if(x!==q.answer)return wrong();$('visual').textContent=g[3]+'  '+x+'  ⭐';return success(r)}
function finish(){locked=true;$('progress').textContent='3 / 3';$('visual').textContent='🎉 '+g[3]+' 🎉';$('instruction').textContent='ぜんぶ できたね！';say('ぜんぶ できたね！');$('choices').replaceChildren();[['🔁 もういちど',intro],['🏠 おうちへ',()=>location.href='../../index.html']].forEach(([t,fn])=>{const b=document.createElement('button');b.className='choice';b.textContent=t;b.onclick=fn;$('choices').append(b)})}
function intro(){rev++;soundBusy=false;try{speechSynthesis.cancel()}catch{}round=0;locked=true;$('progress').textContent='あそびかた';$('visual').textContent=g[3]+'  👆';$('instruction').textContent=g[4];$('feedback').textContent='';$('choices').replaceChildren();const b=document.createElement('button');b.className='choice';b.textContent='▶️ はじめる';b.onclick=()=>{try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume()}catch{}startRound()};$('choices').append(b)}
$('title').textContent=g[1];document.title=g[1];$('repeat').onclick=()=>{if(mode===4&&q&&!locked)siren(q.count,rev);else say(last||g[4])};$('again').onclick=intro;addEventListener('pagehide',()=>{rev++;try{speechSynthesis.cancel()}catch{}});intro();
})();